from transformers import AutoModelForCausalLM

mcfg = cfg["model"]

def load_lm():
    kwargs = {"attn_implementation": mcfg.get("attn_implementation", "sdpa")}
    try:
        lm = AutoModelForCausalLM.from_pretrained(
            mcfg["name"], dtype=torch.bfloat16, **kwargs
        )
    except TypeError:  # transformers < 4.56 uses torch_dtype
        lm = AutoModelForCausalLM.from_pretrained(
            mcfg["name"], torch_dtype=torch.bfloat16, **kwargs
        )
    return lm.to(device)

model = load_lm()
